import{_ as a,o as t,c as o,ae as s}from"./chunks/framework.1Lna8NcP.js";const p=JSON.parse('{"title":"ADR-003: News Feed Integration","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-news-feed.md","filePath":"adr/003-news-feed.md"}'),r={name:"adr/003-news-feed.md"};function n(i,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-003-news-feed-integration" tabindex="-1">ADR-003: News Feed Integration <a class="header-anchor" href="#adr-003-news-feed-integration" aria-label="Permalink to &quot;ADR-003: News Feed Integration&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-05 <strong>Status:</strong> Accepted</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The Dashboard should surface news articles relevant to the user&#39;s holdings and interests (Tech, Politics, Markets, Crypto). This requires an external data source. The app&#39;s privacy-first constraint means no mandatory cloud accounts.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Dual-source news feed:</p><ul><li><strong>RSS feeds</strong> (Reuters, AP, Yahoo Finance) — always available, no API key required, fetched server-side</li><li><strong>NewsAPI</strong> — richer filtering by ticker/topic, requires a free API key stored in <code>.env</code> as <code>NEWS_API_KEY</code></li></ul><p>When both sources are configured, results are merged and deduplicated. Holdings-based results (articles mentioning symbols the user holds) rank above category-based results.</p><p>If <code>NEWS_API_KEY</code> is absent, the app falls back to RSS silently — no error shown to the user.</p><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><p>News is cached in a <code>news_cache</code> table (see spec for schema) to avoid repeated API calls. Cache TTL: 30 minutes. Backend fetches on dashboard load if cache is stale.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><ul><li>No user data is sent to NewsAPI beyond ticker symbols and category keywords</li><li>API key stored in <code>.env</code>, gitignored, never committed</li><li>Settings page shows masked key status only</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>New <code>news</code> router in backend</li><li><code>news_cache</code> table added to DB</li><li><code>NEWS_API_KEY</code> documented in <code>.env.example</code> (no actual key committed)</li><li>RSS parsing library needed (<code>feedparser</code> or equivalent)</li></ul>',16)])])}const f=a(r,[["render",n]]);export{p as __pageData,f as default};
